int fd = 3;
struct stat64 fs_info;
int ret;

// Retrieve 64-bit status for the file linked to fd
ret = fstat64(fd, &fs_info);

if (ret == 0) {
    // Success: Access 64-bit attributes
    off_t file_size = fs_info.st_size;
    mode_t file_mode = fs_info.st_mode;
}

